select case when cost >= 92 then 'high' when cost >= 35 then 'mid' else 'low' end as cost_bucket, sum(cost) as total_cost, sum(sum(cost)) over (order by case when cost >= 92 then 'high' when cost >= 35 then 'mid' else 'low' end) as cumulative_cost from shipments where order_id in (3, 5, 18, 21) group by case when cost >= 92 then 'high' when cost >= 35 then 'mid' else 'low' end order by 1 desc
